  const handleSelect = async (commandId: string) =&gt; {
    setOpen(false);
    setQuery('');
    await execute(commandId);
  };

  return (
    &lt;Command.Dialog
      open={open}
      onOpenChange={setOpen}
      label="Command Palette"
      className="command-dialog"
    &gt;
      &lt;Command.Input
        value={query}
        onValueChange={setQuery}
        placeholder="Type a command or search..."
