}

Optimistic UI Updates
Update the UI immediately, then reconcile with the server response:
function TodoList() {
  const [todos, setTodos] = useState&lt;Todo[]&gt;([]);
  const { send } = useWebSocket('wss://api.example.com/todos');

  const addTodo = (text: string) =&gt; {
    // Create optimistic todo with temp ID
    const optimisticTodo = {
      id: `temp-${Date.now()}`,
      text,
      completed: false,
      isPending: true,
    };

    // Add to UI immediately
    setTodos(prev =&gt; [...prev, optimisticTodo]);

    // Send to server
    send({ type: 'add', text });
  };

  // Handle server confirmation
  useEffect(() =&gt; {
    // When server confirms, replace temp ID with real ID
    // Handle in WebSocket onmessage handler
  }, []);

  return (
    &lt;ul&gt;
      {todos.map(todo =&gt; (
        &lt;li key={todo.id} className={todo.isPending ? 'pending' : ''}&gt;
          {todo.text}
        &lt;/li&gt;
      ))}
    &lt;/ul&gt;
  );
}

Reconnection Strategy
Real-world connections drop. Implement exponential backoff:





stateDiagram-v2
    [*] --&gt; Connecting
    Connecting --&gt; Open: onopen
    Connecting --&gt; Error: onerror
    Open --&gt; Closed: onclose
    Error --&gt; Reconnecting: after delay
    Closed --&gt; Reconnecting: after delay
    Reconnecting --&gt; Connecting: attempt

    note right of Reconnecting
        Exponential backoff:
        1s → 2s → 4s → 8s...
        max 30s
    end note






function useReconnectingWebSocket(url: string) {
  const [status, setStatus] = useState('connecting');
  const reconnectDelay = useRef(1000);

  useEffect(() =&gt; {
    let ws: WebSocket;
    let reconnectTimer: NodeJS.Timeout;

    function connect() {
      ws = new WebSocket(url);

      ws.onopen = () =&gt; {
        setStatus('open');
        reconnectDelay.current = 1000; // Reset delay on success
      };

      ws.onclose = () =&gt; {
        setStatus('reconnecting');
        // Exponential backoff: 1s, 2s, 4s, 8s... max 30s
        reconnectTimer = setTimeout(() =&gt; {
          reconnectDelay.current = Math.min(reconnectDelay.current * 2, 30000);
          connect();
        }, reconnectDelay.current);
      };
    }

    connect();

    return () =&gt; {
      clearTimeout(reconnectTimer);
      ws?.close();
    };
  }, [url]);

  return status;
}

