test('resets when resetErrorBoundary is called', async () =&gt; {
  const user = userEvent.setup();
  let shouldThrow = true;

  function MaybeThrow() {
    if (shouldThrow) throw new Error('Test error');
    return &lt;div&gt;Success&lt;/div&gt;;
  }

  render(
    &lt;ErrorBoundary
      FallbackComponent={({ resetErrorBoundary }) =&gt; (
        &lt;button onClick={resetErrorBoundary}&gt;Reset&lt;/button&gt;
      )}
      onReset={() =&gt; { shouldThrow = false; }}
    &gt;
      &lt;MaybeThrow /&gt;
    &lt;/ErrorBoundary&gt;
  );

  await user.click(screen.getByText('Reset'));
  expect(screen.getByText('Success')).toBeInTheDocument();
});

Error boundaries transform your app from “one crash kills everything” to “graceful degradation with user feedback.” Place them strategically, log errors properly, and always give users a way to recover.

TanStack Table: The Flexible Choice
TanStack Table (formerly React Table) is the most popular headless table library. It provides all the logic — sorting, filtering, pagination, virtualization — while you own the markup.

Installation
npm install @tanstack/react-table


Basic Table Setup
// src/components/BasicTable.tsx
import {
  useReactTable,
  getCoreRowModel,
  flexRender,
  createColumnHelper,
} from '@tanstack/react-table';

interface User {
  id: number;
  name: string;
  email: string;
  status: 'active' | 'inactive';
}

const columnHelper = createColumnHelper&lt;User&gt;();

const columns = [
  columnHelper.accessor('id', {
    header: 'ID',
    cell: (info) =&gt; info.getValue(),
  }),
  columnHelper.accessor('name', {
    header: 'Name',
    cell: (info) =&gt; &lt;strong&gt;{info.getValue()}&lt;/strong&gt;,
  }),
  columnHelper.accessor('email', {
    header: 'Email',
  }),
  columnHelper.accessor('status', {
    header: 'Status',
    cell: (info) =&gt; (
      &lt;span className={`badge badge-${info.getValue()}`}&gt;
        {info.getValue()}
      &lt;/span&gt;
    ),
  }),
];

export function BasicTable({ data }: { data: User[] }) {
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
  });

  return (
    &lt;table&gt;
      &lt;thead&gt;
        {table.getHeaderGroups().map((headerGroup) =&gt; (
          &lt;tr key={headerGroup.id}&gt;
            {headerGroup.headers.map((header) =&gt; (
              &lt;th key={header.id}&gt;
                {flexRender(
                  header.column.columnDef.header,
                  header.getContext()
                )}
              &lt;/th&gt;
            ))}
          &lt;/tr&gt;
        ))}
      &lt;/thead&gt;
      &lt;tbody&gt;
        {table.getRowModel().rows.map((row) =&gt; (
          &lt;tr key={row.id}&gt;
            {row.getVisibleCells().map((cell) =&gt; (
              &lt;td key={cell.id}&gt;
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              &lt;/td&gt;
            ))}
          &lt;/tr&gt;
        ))}
      &lt;/tbody&gt;
    &lt;/table&gt;
  );
}

